from taf.analyzer.base.log_reader import LogReader
from taf.converters.eventdecoder.tti_event_reader import TtiEventReader
from .ttitrace_event import TtitraceEvent


class TtitraceReader(LogReader):
    """
    Read eventDecoder decoded json file and handle each TTITrace Event

    Usage:

        Code::

            from taf.analyzer.ttitrace_eventdecoder import TtitraceReader

            file_name = '/tmp/ttitrace.json'

            with open(file_name, 'rb') as file_obj:
                for event in TtitraceReader(
                        file_obj=file_obj):
                    # handle event

            # usage with LogReader method from_file()
            for event in TtitraceReader.from_file(file_name):
                # handle event
    """

    def __init__(self, file_obj, tti_event_reader=None, **kwargs):
        super(TtitraceReader, self).__init__(file_obj=file_obj, **kwargs)
        if tti_event_reader is None:
            tti_event_reader = TtiEventReader(file_obj=file_obj)
        self._tti_event_reader = tti_event_reader

    def _get_tti_event(self, d):
        """
            Override method from incremental json parser in taf.converters.eventdecoder.tti_event_reader
            to return the decoded event wrapped as TtiTraceEvent
        """
        return TtitraceEvent(d)

    def __iter__(self):
        for ttievent in self._tti_event_reader:
            yield self._get_tti_event(ttievent)
